"use client"

import type React from "react"
import { mergeProps } from "@base-ui/react/merge-props"
import { useRender } from "@base-ui/react/use-render"
import { cn } from "@/lib/utils"
import { cva, type VariantProps } from "class-variance-authority"

import "@/styles/surface.styles.css"

const cardVariants = cva("cn-card", {
  variants: {
    variant: {
      default: "",
      outline: "cn-card-outline",
      elevated: "cn-card-elevated",
      ghost: "cn-card-ghost",
    },
  },
  defaultVariants: { variant: "default" },
})

export function Card({
  className,
  render,
  variant,
  size = "default",
  ...props
}: useRender.ComponentProps<"div"> &
  VariantProps<typeof cardVariants> & { size?: "default" | "sm" | "lg" }): React.ReactElement {
  const defaultProps = {
    className: cn(cardVariants({ variant }), className),
    "data-slot": "card",
    "data-variant": variant,
    "data-size": size,
  }

  return useRender({
    defaultTagName: "div",
    props: mergeProps<"div">(defaultProps, props),
    render,
  })
}

export function CardFrame({
  className,
  render,
  ...props
}: useRender.ComponentProps<"div">): React.ReactElement {
  const defaultProps = {
    className: cn("cn-card-frame", className),
    "data-slot": "card-frame",
  }

  return useRender({
    defaultTagName: "div",
    props: mergeProps<"div">(defaultProps, props),
    render,
